function startRift(){if(loading||modalType)return;if(S.mode!=='overworld'){toast('Return to Hearthvale before starting a new expedition.');return}if(S.inventory.riftKeys<1){openPanel('forge');toast('A Rift Key costs 4 earned Forge Sigils. The open world is always free.');return}S.inventory.riftKeys--;S.mode='rift';S.rift={wave:1,phase:'combat',boons:[],exitX:player().x,exitY:player().y,kills:0,arenaSeed:(S.stats.kills*17+S.worldTime|0)};player().x=0;player().y=0;player().hp=Math.max(player().hp,65);player().warmth=85;selectedWaypoint=null;enemies.clear();projectiles=[];spawnRiftWave();setDirty();toast('ᛟ THE FROSTBOUND RIFT OPENS · WAVE 1/5');renderPanel()}
