 const biomeNow=biomeName(terrain(p.x,p.y).biome);if(biomeNow!==biomeAnnounced){biomeAnnounced=biomeNow;updateUI('realmLocationBanner',biomeNow);const banner=$('realmLocationCard');if(banner){banner.classList.remove('show');void banner.offsetWidth;banner.classList.add('show')}}
