// Textured atlas uses original deterministic vector artwork. Every world tile remains addressable.
const tileTextures=new Map();
function baseHex(hex){const a=hex.replace('#','');return [0,2,4].map(i=>parseInt(a.slice(i,i+2),16))}
function terrainTexture(biome,variant){const key=biome+':'+variant;if(tileTextures.has(key))return tileTextures.get(key);
 const c=document.createElement('canvas');c.width=48;c.height=48;const g=c.getContext('2d'),color=BIOME_COLORS[biome]?.[1]||'#26493c';g.fillStyle=color;g.fillRect(0,0,48,48);
 const [red,green,blue]=baseHex(color);const image=g.getImageData(0,0,48,48),data=image.data;let seed=(variant+1)*37+biome.length*47;
 // Fine-grained, low-contrast dithering breaks the old checkerboard without changing biomes.
 for(let y=0;y<48;y++)for(let x=0;x<48;x++){const idx=(y*48+x)*4,grain=(hash(x+seed,y-seed,19)-.5)*21;let m=biome==='lake'?5:biome==='snow'?13:11;const band=noise(x+variant*71,y-variant*31,18,biome.length*17+variant)*12-6;
  data[idx]=clamp(red+grain*.52+band,m,249);data[idx+1]=clamp(green+grain*.7+band,m,248);data[idx+2]=clamp(blue+grain*.51+band,m,249);}
 g.putImageData(image,0,0);
 for(let i=0;i<13;i++){const x=hash(i,variant,biome.length+31)*48,y=hash(i,variant+3,biome.length+47)*48;
  if(biome==='lake'){g.strokeStyle='#b4e4e728';g.beginPath();g.ellipse(x,y,8+hash(i,2,variant)*12,1.4,-.12,0,Math.PI);g.stroke()}
  else if(biome==='snow'){g.fillStyle='#f1f7f337';g.beginPath();g.ellipse(x,y,2.8,1.1,0,0,TAU);g.fill()}
  else if(biome==='forest'||biome==='meadow'||biome==='marsh'){g.strokeStyle=biome==='marsh'?'#a7dfc221':'#add1972d';g.lineWidth=.8;g.beginPath();g.moveTo(x,y);g.lineTo(x+hash(i,8,variant)*4-2,y-3-hash(i,7,variant)*4);g.stroke()}
  else {g.fillStyle='#c4b39924';g.beginPath();g.ellipse(x,y,2.5,1.2,0,0,TAU);g.fill()}}
 tileTextures.set(key,c);return c;
}
function paintBaseTile(ctx,tx,ty,x,y,W){
 const t=terrain(tx,ty),biome=S.mode==='rift'?'rift':t.biome,variant=(hash(tx,ty,S.seed+131)*7)|0,palette=BIOME_COLORS[biome];
 ctx.drawImage(terrainTexture(biome,variant),Math.floor(x),Math.floor(y),Math.ceil(W)+1,Math.ceil(W)+1);
 if(S.mode==='rift'){ctx.fillStyle='#98a6d320';ctx.fillRect(x+W*.08,y+W*.07,W*.85,1);return;}
 // Neighbor-colored soft margins blend distinct terrain cells instead of sharp grid lines.
 const dirs=[[0,-1,'top'],[0,1,'bottom'],[-1,0,'left'],[1,0,'right']];
 for(const [dx,dy,edge] of dirs){const other=terrain(tx+dx,ty+dy).biome;if(other===biome)continue;
 const color=BIOME_COLORS[other][1],g=edge==='left'?ctx.createLinearGradient(x,y,x+W*.6,y):edge==='right'?ctx.createLinearGradient(x+W,y,x+W*.4,y):edge==='top'?ctx.createLinearGradient(x,y,x,y+W*.6):ctx.createLinearGradient(x,y+W,x,y+W*.4);
 const [r,gg,b]=baseHex(color);g.addColorStop(0,`rgba(${r},${gg},${b},.33)`);g.addColorStop(1,`rgba(${r},${gg},${b},0)`);ctx.fillStyle=g;ctx.fillRect(x,y,W+1,W+1);
 }
 if(biome==='lake'){const drift=Math.sin(simElapsed*.9+t.r*10)*2;ctx.strokeStyle='#c2eeee3f';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+W*.13,y+W*.4+drift);ctx.quadraticCurveTo(x+W*.5,y+W*.25,x+W*.84,y+W*.4+drift);ctx.stroke();return;}
 if(Math.abs(ty)<.7&&tx>-6&&tx<6){ctx.fillStyle='#b7a27e17';ctx.fillRect(x,y+W*.3,W,W*.45)}
 if(tx>2&&tx<13&&Math.abs(ty+tx*.72-2)<.95){ctx.fillStyle='#b2aa7b1c';ctx.fillRect(x+W*.25,y+W*.25,W*.65,W*.55)}
}

const TERRAIN_CHUNK=8,terrainChunks=new Map();
function terrainChunk(cx,cy){const key=S.seed+':'+(S.mode==='rift'?'rift':'world')+':'+cx+':'+cy;
 const found=terrainChunks.get(key);if(found){terrainChunks.delete(key);terrainChunks.set(key,found);return found}
 const side=TERRAIN_CHUNK*48,c=document.createElement('canvas');c.width=side;c.height=side;const g=c.getContext('2d');
 for(let iy=0;iy<TERRAIN_CHUNK;iy++)for(let ix=0;ix<TERRAIN_CHUNK;ix++){
  paintBaseTile(g,cx*TERRAIN_CHUNK+ix,cy*TERRAIN_CHUNK+iy,ix*48,iy*48,48);
 }
 terrainChunks.set(key,c);
 // Eviction affects only rendered pixels. Every location regenerates identically on demand.
 while(terrainChunks.size>96)terrainChunks.delete(terrainChunks.keys().next().value);
 return c;
}
function drawTerrainChunks(minX,maxX,minY,maxY){const loX=Math.floor(minX/TERRAIN_CHUNK),hiX=Math.floor(maxX/TERRAIN_CHUNK),loY=Math.floor(minY/TERRAIN_CHUNK),hiY=Math.floor(maxY/TERRAIN_CHUNK),size=TERRAIN_CHUNK*W;
 for(let cy=loY;cy<=hiY;cy++)for(let cx=loX;cx<=hiX;cx++){const tex=terrainChunk(cx,cy),pt=screen(cx*TERRAIN_CHUNK,cy*TERRAIN_CHUNK);ctx.drawImage(tex,Math.floor(pt.x),Math.floor(pt.y),Math.ceil(size)+1,Math.ceil(size)+1)}
}
function drawPine(x,y,snow=false){ctx.save();ctx.translate(x,y);ellipse(0,8,20,9,'#0007');ctx.fillStyle='#624b35';ctx.fillRect(-3,-12,6,20);
 for(let i=0;i<3;i++){const h=42-i*15,w=20-i*4,dy=-30+i*11;drawPoly([[0,dy-h*.55],[-w,dy+17],[w,dy+17]],snow?(i%2?'#356f63':'#427668'):(i%2?'#1d5143':'#2d6550'),'#091b1d66',1);line(-w+2,dy+17,0,dy-h*.55,snow?'#b0d5d2a2':'#7ea87b4f',1)}if(snow){ellipse(-7,-19,9,2.8,'#cfebebac');ellipse(5,-30,6,2,'#e6f1e7b4')}ctx.restore()}
