function drawBerry(x,y){ellipse(x,y+10,15,6,'#091b19af');for(let i=0;i<6;i++){const a=i*TAU/6;const bx=x+Math.cos(a)*9,by=y+Math.sin(a)*5;ellipse(bx,by,7,5,i%2?'#44734b':'#3d7152');ellipse(bx+3,by-3,2,2,i%2?'#ca688a':'#e7ae71')}}
