function drawRuin(x,y){ellipse(x,y+6,20,9,'#07151c9e');ctx.fillStyle='#53615c';ctx.fillRect(x-15,y-15,8,21);ctx.fillRect(x+10,y-24,9,29);drawPoly([[x-20,y-15],[x-12,y-23],[x-3,y-15]],'#a5aba4');line(x-9,y+3,x+10,y+7,'#8fd6c774',2);ctx.font='14px Georgia';ctx.fillStyle='#a7ffe5';ctx.fillText('ᛟ',x-2,y)}
function drawCamp(x,y){ctx.save();ctx.translate(x,y);ellipse(0,13,70,34,'#0919128e');const glow=ctx.createRadialGradient(0,0,2,0,0,92);glow.addColorStop(0,'#eeb47338');glow.addColorStop(1,'transparent');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,92,0,TAU);ctx.fill();
 for(let i=0;i<10;i++){const a=i*TAU/10;ellipse(Math.cos(a)*21,Math.sin(a)*10+8,6,4,'#889080')}
 const t=performance.now()/850;drawPoly([[-2,9],[-8,-8+Math.sin(t)*4],[2,-26+Math.cos(t)*7],[13,-4+Math.sin(t)*3],[4,9]],'#fcb64b');drawPoly([[0,8],[-2,-5],[5,-16+Math.sin(t)*4],[9,3]],'#ffeeb4');line(-11,11,12,6,'#664834',3);line(-7,4,9,13,'#72523b',3);ctx.restore()}
