function drawHall(x,y){ctx.save();ctx.translate(x,y);ellipse(0,15,64,25,'#0007');ctx.fillStyle='#685d46';ctx.fillRect(-43,-28,87,49);drawPoly([[-52,-28],[0,-71],[52,-28]],'#4c635a','#b3b19b',2);drawPoly([[-45,-28],[0,-57],[42,-28]],'#77967c88');ctx.fillStyle='#31271a';ctx.fillRect(-12,-17,23,37);ctx.fillStyle='#f4c97a';ctx.fillRect(-29,-12,8,11);ctx.fillRect(21,-12,8,11);ctx.restore()}
function drawTreeNode(x,y,obj){const key=obj.id||'';if(S.harvested[key]&&S.harvested[key]>S.worldTime){if(obj.type==='tree'||obj.type==='snowpine'){ellipse(x,y+10,11,5,'#142322');ctx.fillStyle='#755944';ctx.fillRect(x-3,y,5,8)}else if(obj.type==='rock'){ellipse(x,y+4,9,4,'#54665b')}return}
 switch(obj.type){case'tree':case'snowpine':drawPine(x,y,obj.type==='snowpine');break;case'rock':drawRock(x,y);break;case'berry':drawBerry(x,y);break;case'herb':drawHerb(x,y);break;case'ruin':drawRuin(x,y);break;case'camp':drawCamp(x,y);break;case'forge':drawForge(x,y);break;case'merchant':drawTrader(x,y);break;case'portal':drawPortal(x,y);break;case'shrine':drawRuin(x,y);break;case'obelisk':drawPortal(x,y);break}}
function drawEnemy(e){const {x,y}=screen(e.x,e.y);if(x<-50||x>cw+50||y<-50||y>ch+50)return;ctx.save();ctx.translate(x,y);ellipse(0,11,e.boss?25:14,e.boss?11:6,'#061312a6');const t=performance.now()/300;
 if(e.windup>0){const fraction=1-e.windup/Math.max(.1,e.windupTotal);ctx.save();ctx.strokeStyle=e.boss?'#ffd393':'#ff9e7f';ctx.lineWidth=3+fraction*2;ctx.shadowBlur=17;ctx.shadowColor='#f59162';ctx.beginPath();ctx.arc(0,0,(e.boss?39:26)-6*fraction,-PI/2,-PI/2+TAU*fraction);ctx.stroke();ctx.restore();}
 if(e.type==='wolf'){drawPoly([[-14,5],[-13,-5],[-7,-13],[0,-5],[11,-13],[13,5],[1,11]],'#a9b5a2','#243c3b',1.4);drawPoly([[-10,-7],[-8,-20],[0,-9],[9,-20],[11,-6]],'#7f998c');ellipse(-5,-3,2,2,'#e8d38b');ellipse(5,-3,2,2,'#e8d38b')}
 else if(e.type==='wraith'){ellipse(0,-11,13,20,'#8abddfa6');drawPoly([[-13,-12],[-7,-23],[0,-33],[9,-21],[13,6],[-5,13]],'#c6edfa70');ellipse(-5,-12,2,2,'#fff');ellipse(5,-12,2,2,'#fff')}
 else{drawPoly([[-14,9],[-10,-10],[0,-25],[13,-12],[17,10]],e.boss?'#55517a':'#8c6960','#252b38',1.3);ellipse(0,-17,8,9,'#aa8d7d');drawPoly([[-10,-25],[-4,-32],[6,-32],[10,-25]],e.boss?'#b6a4ef':'#737989');line(13,-5,22,-20,'#e9dca6',2)}
 if(e.hp<e.maxHp||e.boss){ctx.fillStyle='#081017ba';ctx.fillRect(-18,-36,36,4);ctx.fillStyle=e.boss?'#d4a6ed':'#ce717c';ctx.fillRect(-18,-36,36*clamp(e.hp/e.maxHp,0,1),4)}ctx.restore()}
function drawCompanion(){if(!S.companions.includes('frostpaw'))return;const p=player(),x=p.x-1.1+Math.sin(performance.now()/600)*.22,y=p.y+.8;const pt=screen(x,y);ellipse(pt.x,pt.y+6,12,6,'#031619ba');drawPoly([[pt.x-10,pt.y+4],[pt.x-8,pt.y-6],[pt.x,pt.y-10],[pt.x+9,pt.y-6],[pt.x+11,pt.y+5]],'#c5d9d4');ellipse(pt.x-3,pt.y-4,2,2,'#6dd5e0');ellipse(pt.x+3,pt.y-4,2,2,'#6dd5e0')}
