function drawMinimap(){const size=132,p=player(),left=cw-size-15,top=16,tiles=13,step=size/tiles;ctx.save();ctx.fillStyle='#06181ce5';ctx.fillRect(left-4,top-4,size+8,size+8);ctx.strokeStyle='#d0bd8b';ctx.lineWidth=1;ctx.strokeRect(left-4,top-4,size+8,size+8);
 for(let y=0;y<tiles;y++)for(let x=0;x<tiles;x++){const wx=Math.floor(p.x)+x-6,wy=Math.floor(p.y)+y-6;const t=terrain(wx,wy),palette=BIOME_COLORS[S.mode==='rift'?'rift':t.biome];ctx.fillStyle=palette[1];ctx.fillRect(left+x*step,top+y*step,step+1,step+1)}
 if(S.mode==='overworld')for(const q of Object.values(POIS)){const dx=q.x-p.x,dy=q.y-p.y;if(Math.abs(dx)<7&&Math.abs(dy)<7){const px=left+(dx+6.5)*step,py=top+(dy+6.5)*step;ellipse(px,py,3,3,'#f0da9c')}}
 ellipse(left+6.5*step,top+6.5*step,4,4,'#fff2bd');ctx.strokeStyle='#091f21';ctx.strokeRect(left,top,size,size);ctx.restore()}
function renderWorld(){const frameStart=performance.now();resize();ctx.clearRect(0,0,cw,ch);const p=player();camX=lerp(camX,p.x,.18);camY=lerp(camY,p.y,.18);ctx.fillStyle='#21382f';ctx.fillRect(0,0,cw,ch);
 ctx.save();if(hitShake>0&&!reducedMotion())ctx.translate(Math.sin(simElapsed*91)*hitShake*10,Math.cos(simElapsed*107)*hitShake*8);
 const minX=Math.floor(camX-cw/W/2)-2,maxX=Math.ceil(camX+cw/W/2)+2,minY=Math.floor(camY-ch/W/2)-2,maxY=Math.ceil(camY+ch/W/2)+2;
 renderMetrics.tiles=(maxX-minX+1)*(maxY-minY+1);
 drawTerrainChunks(minX,maxX,minY,maxY);let props=[];if(S.mode!=='rift')for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){const obj=objectAt(x,y);if(obj)props.push({y:y+.5,kind:'obj',x,y,obj})}
 if(S.mode==='rift'){const c=screen(0,0);ctx.save();ctx.strokeStyle='#9393da66';for(let i=0;i<3;i++){ctx.lineWidth=i?2:9;ctx.beginPath();ctx.arc(c.x,c.y,(12.6-i*.7)*W,0,TAU);ctx.stroke()}for(let i=0;i<16;i++){const a=i*TAU/16,t=screen(Math.cos(a)*12,Math.sin(a)*12);ctx.fillStyle=i%2?'#ada8d1':'#7caec4';ctx.font='27px Georgia';ctx.fillText('ᛟ',t.x-12,t.y+9)}ctx.restore()}
 else{for(const f of S.camp.fires)if(f.x>=minX&&f.x<=maxX&&f.y>=minY&&f.y<=maxY)props.push({y:f.y,kind:'fire',x:f.x,y0:f.y});if(S.camp.hall)props.push({y:3,kind:'hall',x:-2,y0:3})}
 for(const e of enemies.values())props.push({y:e.y,kind:'enemy',e});props.push({y:p.y,kind:'player'});if(S.companions.includes('frostpaw'))props.push({y:p.y+.8,kind:'companion'});
 props.sort((a,b)=>a.y-b.y);for(const q of props){if(q.kind==='obj'){const t=screen(q.x+.5,q.y+.58);drawTreeNode(t.x,t.y,q.obj)}else if(q.kind==='enemy')drawEnemy(q.e);else if(q.kind==='player')drawPlayer();else if(q.kind==='companion')drawCompanion();else if(q.kind==='hall'){const t=screen(q.x,q.y0);drawHall(t.x,t.y)}else if(q.kind==='fire'){const t=screen(q.x,q.y0);drawCamp(t.x,t.y)}}
 if(S.mode==='expedition'&&S.rift){const pts=S.rift.relicSites||[{x:73,y:-65},{x:79,y:-58},{x:66,y:-52}];for(let i=0;i<pts.length;i++)if(!S.rift.seen.includes(i)){const z=screen(pts[i].x,pts[i].y);if(z.x>-20&&z.x<cw+20&&z.y>-20&&z.y<ch+20){ctx.font='32px Georgia';ctx.fillStyle='#dac9ff';ctx.shadowColor='#a794df';ctx.shadowBlur=22;ctx.fillText('ᛟ',z.x-10,z.y);ctx.shadowBlur=0}}}
 drawProjectiles();for(const f of particles){const s=screen(f.x,f.y);ctx.globalAlpha=f.life;ellipse(s.x,s.y,f.size,f.size,f.color)}ctx.globalAlpha=1;
 if(selectedWaypoint){const pt=screen(selectedWaypoint.x,selectedWaypoint.y);ctx.strokeStyle='#f5dba7cc';ctx.lineWidth=2;ctx.beginPath();ctx.arc(pt.x,pt.y,8+Math.sin(performance.now()/180)*2,0,TAU);ctx.stroke();line(pt.x-13,pt.y,pt.x+13,pt.y,'#f5dba7aa');line(pt.x,pt.y-13,pt.x,pt.y+13,'#f5dba7aa')}
 ctx.restore(); // World camera shake never displaces the minimap, HUD, or click targets.
 drawAtmosphere();
 const light=ctx.createRadialGradient(cw*.5,ch*.43,35,cw*.5,ch*.5,Math.max(cw,ch)*.77);light.addColorStop(0,'#fffde200');light.addColorStop(.63,'#0e191d0b');light.addColorStop(1,'#030b0f77');ctx.fillStyle=light;ctx.fillRect(0,0,cw,ch);
 for(const f of combatFloats){const pt=screen(f.x,f.y);ctx.save();ctx.globalAlpha=clamp(f.life/.8,0,1);ctx.textAlign='center';ctx.font='900 17px Georgia,serif';ctx.lineWidth=3;ctx.strokeStyle='#11151c';ctx.strokeText(f.text,pt.x,pt.y-15);ctx.fillStyle=f.color;ctx.fillText(f.text,pt.x,pt.y-15);ctx.restore()}
 if(damageTint>0&&!reducedMotion()){ctx.fillStyle=`rgba(178,34,56,${(damageTint*.22).toFixed(3)})`;ctx.fillRect(0,0,cw,ch)}drawMinimap();
 if(S.mode==='expedition'){ctx.fillStyle='#e8cb8f';ctx.font='800 12px system-ui';ctx.fillText(`IRONMAN · ${S.rift?.relics||0}/3 RELICS · ${Math.max(0,90-Math.floor(S.rift?.seconds||0))}s`,Math.max(10,cw-245),Math.max(166,ch-18))}
 if(S.mode==='rift'){ctx.fillStyle='#f4d8ac';ctx.font='800 13px Georgia';ctx.textAlign='center';ctx.fillText(`ᛟ WAVE ${S.rift?.wave||1}/5  ·  ${enemies.size} FOES REMAIN`,cw/2,ch-26);ctx.textAlign='left'}
 renderMetrics.last=performance.now()-frameStart;
}
function drawAtmosphere(){
 const phase=(S.worldTime%180)/180,daylight=(1+Math.cos(phase*TAU-PI))/2,dark=clamp((1-daylight)*.72,0,.72);
 if(dark>.012){ctx.fillStyle=`rgba(3,9,24,${dark.toFixed(3)})`;ctx.fillRect(0,0,cw,ch);
  const lights=[{x:0,y:0,power:240},{x:-4,y:0,power:120},...S.camp.fires.map(f=>({x:f.x,y:f.y,power:165}))];
  ctx.save();ctx.globalCompositeOperation='screen';for(const q of lights){const pt=screen(q.x,q.y);if(pt.x< -q.power||pt.x>cw+q.power||pt.y< -q.power||pt.y>ch+q.power)continue;const g=ctx.createRadialGradient(pt.x,pt.y,6,pt.x,pt.y,q.power);g.addColorStop(0,`rgba(254,185,90,${(.42+dark*.17).toFixed(2)})`);g.addColorStop(.35,'rgba(236,144,67,.14)');g.addColorStop(1,'rgba(235,131,75,0)');ctx.fillStyle=g;ctx.fillRect(pt.x-q.power,pt.y-q.power,2*q.power,2*q.power)}ctx.restore();}
 // Weather is deterministic, screen anchored and drawn after the world layer.
 const kind=worldWeather();if(kind==='clear')return;
 if(reducedMotion()){if(kind==='mist'){ctx.fillStyle='#b5d8ce0a';ctx.fillRect(0,ch*.36,cw,ch*.4)}return}
 const count=kind==='blizzard'?140:kind==='snow'?75:kind==='rain'?88:kind==='arcane'?80:kind==='mist'?30:44;
 ctx.save();for(let i=0;i<count;i++){
  const phase=hash(i,53,S.seed),spread=hash(i,61,S.seed),velocity=kind==='rain'?360:kind==='blizzard'?170:kind==='snow'?64:kind==='arcane'?85:kind==='mist'?19:45;
  const x=((phase*cw+(simElapsed*velocity*(kind==='rain'?.19:.52))+(Math.sin(simElapsed*.3+i)*12))%(cw+40)+cw+40)%(cw+40)-20;
  const y=((spread*ch+simElapsed*velocity)%(ch+30)+ch+30)%(ch+30)-15;
  if(kind==='rain'){line(x,y,x-6,y+19,'#b3c9d25a',1.15);continue}
  if(kind==='mist'){ellipse(x,y,58,14,'#c9e5dd0e');continue}
  if(kind==='embers'){ellipse(x,y,1.3+spread*1.9,1.9,'#fa985b91');continue}
  if(kind==='arcane'){ctx.font='15px Georgia';ctx.fillStyle='#b8b6f5a0';ctx.fillText('ᛟ',x,y);continue}
  ellipse(x,y,kind==='blizzard'?2.3:1.3+spread*1.3,kind==='blizzard'?2.3:1.3+spread*1.3,'#f5fffbab');
 }ctx.restore();
}

function showModal(type,kicker,title,content,buttons=[]){modalType=type;const m=$('realmModal');m.hidden=false;updateUI('realmModalKicker',kicker);updateUI('realmModalTitle',title);$('realmModalContent').innerHTML=content;$('realmModalActions').innerHTML=buttons.map(b=>`<button class="realm-gold" data-action="${b.action}">${b.label}</button>`).join('');$('realmModalClose').focus()}
function closeModal(){modalType='';$('realmModal').hidden=true;canvas.focus({preventScroll:true})}
function showMap(){const st=S.mode==='rift'?'The arena stands between worlds.':S.mode==='expedition'?'Roguelite survival expedition.':'Your world grows each time you venture outward.';
 showModal('map','◇ CARTOGRAPHER OF SHIVERFELL','THE NORTHERN WILDS',`<p>${st}</p><canvas id="realmMapCanvas" width="550" height="350" style="display:block;width:100%;border:1px solid #82988e;border-radius:6px;background:#142d2b;cursor:crosshair" aria-label="World map; select a destination to set a waypoint"></canvas><p><small>Gold: settlements and ancient landmarks. Recover three Dawnshards (shrine, watchtower, crypt) to awaken the Ashen Obelisk. Teal: your location. Click to set a waypoint. Explored regions remain remembered.</small></p>`,[{label:'RETURN TO THE WILDS',action:'close-modal'}]);const c=$('realmMapCanvas'),g=c.getContext('2d'),p=player(),scale=.72;const w=c.width,h=c.height;
 for(let y=0;y<h;y+=6)for(let x=0;x<w;x+=6){const tx=Math.floor(p.x+(x-w/2)*scale),ty=Math.floor(p.y+(y-h/2)*scale),t=terrain(tx,ty);g.fillStyle=BIOME_COLORS[t.biome][1];g.fillRect(x,y,7,7)}
 for(const [id,poi] of Object.entries(POIS)){const x=w/2+(poi.x-p.x)/scale,y=h/2+(poi.y-p.y)/scale;if(x>0&&x<w&&y>0&&y<h){g.fillStyle=id==='obelisk'?'#e99d8f':S.story.fragments.includes(id)?'#6bd9bb':'#f9dba9';g.beginPath();g.arc(x,y,5,0,TAU);g.fill();g.fillStyle='#f5e9cb';g.font='11px Georgia';g.fillText(poi.name.slice(0,24),x+8,y+4)}}
 g.fillStyle='#a8ffeb';g.beginPath();g.arc(w/2,h/2,7,0,TAU);g.fill();g.strokeStyle='#081b1c';g.stroke();c.addEventListener('click',e=>{const rect=c.getBoundingClientRect(),mx=(e.clientX-rect.left)/rect.width*w,my=(e.clientY-rect.top)/rect.height*h;selectedWaypoint={x:p.x+(mx-w/2)*scale,y:p.y+(my-h/2)*scale};closeModal();toast('◇ Waypoint set on your cartographer map.');})}
function help(){showModal('help','✧ SURVIVAL FIELD MANUAL','WELCOME TO SHIVERFELL',`<p>Follow the glowing trail beyond Hearthvale. Recover three Dawnshards at the Whispering Shrine, Sentinel Watchtower, and Sundered Crypt, then face the Ashen Warden at the obelisk. The land is procedurally generated. Hunt wolves, defeat bandits, gather timber and herbs, build campfires and search forgotten ruins. Hunger, stamina and cold are real survival mechanics. Return to your camp to recover.</p><p><b>WASD / Arrows:</b> move · <b>Shift:</b> sprint · <b>Space:</b> dodge · <b>F / Click:</b> sword · <b>Q:</b> bow · <b>1 / 2:</b> ember / frost magic · <b>E:</b> gather and interact · <b>M:</b> map · <b>T:</b> talent tree · <b>Escape:</b> pause. Gamepads: left stick to move, right stick to aim, A attack, B dodge, X interact, Y heal, shoulder buttons for ranged and magic. Clicking empty ground also sets a movement destination.</p><p>Earn 10 Forge Sigils for each unique verified mod update in your native MO2 Chronicle. Spend them on permanent gear or consumable rift keys. The offline training realm uses its own clearly separate practice wallet. Explore free, forever.</p><p><b>Roguelite:</b> Frostbound Rift has 5 increasingly difficult arena waves with blessing drafts; Wilderness Ironman is a one-life relic expedition. The original game uses no downloaded Skyrim assets or music.</p>`,[{label:'BEGIN THE ADVENTURE',action:'close-modal'}])}
function renderWallet(){updateUI('realmCoins',Math.max(0,wallet.available));updateUI('realmShopBalance',Math.max(0,wallet.available));updateUI('realmWalletSource',connected?`${wallet.verifiedUpdates} VERIFIED MOD UPDATES`:'OFFLINE PRACTICE · NOT RANKED');updateUI('realmBridgeInfo',connected?`MO2 PROFILE: ${profileId.split(':').at(-1).slice(0,20)}`:'PRACTICE · OFFLINE');updateUI('realmEarnedLabel',connected?`${wallet.earned} earned · ${wallet.spent} spent · 10 per update`:'30 starter credits · practice only');updateUI('realmForgeIntro',connected?'Your Sigils are minted from real, deduplicated MO2 upgrades. Spends are verified by your active MO2 Chronicle.':'Offline practice has 30 trial Sigils to test crafting, gear and roguelite runs. Practice purchases never award MO2 XP or carry into ranked play.')}
function renderHUD(){const p=player(),maxhp=maxHP();for(const [val,id,fill,max] of [[p.hp,'realmHpText','realmHpFill',maxhp],[p.stamina,'realmStaminaText','realmStaminaFill',100],[p.hunger,'realmHungerText','realmHungerFill',100],[p.warmth,'realmWarmthText','realmWarmthFill',100]]){updateUI(id,val.toFixed(0)+(id==='realmHpText'?'/'+maxhp:'%'));$(fill).style.width=clamp(val/max*100,0,100).toFixed(1)+'%'}
 const env=S.mode==='rift'?'rift':terrain(p.x,p.y).biome;updateUI('realmBiome',biomeName(env));updateUI('realmWeather',WEATHER_NAMES[worldWeather()]||'CLEAR SKIES');updateUI('realmCombo',combatCombo>1&&comboWindow>0?`${combatCombo} HIT COMBO · ${Math.ceil(comboWindow*10)/10}s`:'');const hour=round(((S.worldTime%180)/180)*24)%24,part=hour<6?'MIDNIGHT':hour<11?'DAWN':hour<18?'DAYLIGHT':'DUSK';updateUI('realmTime',`DAY ${Math.floor(S.worldTime/180)+1} · ${String(hour).padStart(2,'0')}:00 · ${part}`);updateUI('realmCoord',`${round(p.x)} E · ${round(-p.y)} N`);updateUI('realmModeLabel',S.mode==='rift'?`ᛟ RIFT · WAVE ${S.rift?.wave||1}/5`:S.mode==='expedition'?'♞ IRONMAN EXPEDITION':'OPEN WORLD · SURVIVAL');updateUI('realmHeroTitle',`LVL ${p.level} · ${p.level>=10?'DRAGONKIN HERO':p.level>=5?'WAYFINDER':'UNBOUND WANDERER'}`);updateUI('realmExpNumber',`${p.xp} / ${p.level*90} XP`);$('realmExpFill').style.width=clamp(100*p.xp/(p.level*90),0,100)+'%';const interact=nearestInteraction();updateUI('realmActionCue',interact?`E · ${interact.obj.name.toUpperCase()}`:S.mode==='rift'?'⚔ SURVIVE THE WAVES':S.mode==='expedition'?'♞ COLLECT RELICS · SURVIVE':'E · INTERACT / GATHER');updateUI('realmSaveState',loading?'LOADING WORLD...':saved?'✧ WORLD SAVED · '+(connected?'MO2 CHRONICLE':'LOCAL'):'✧ EXPLORING · SAVE PENDING')}
function renderQuests(){const complete=QUESTS.filter(q=>S.quests[q.id]).length;updateUI('realmStoryProgress',`${S.story.fragments.length}/3 DAWNSHARDS · ${S.story.wardenDefeated?'WARDEN VANQUISHED':'THE ASHEN WARDEN AWAITS'}`);const title=$('realmQuests');title.innerHTML=QUESTS.map((q,i)=>{const n=q.progress(S),done=Boolean(S.quests[q.id]);return `<article class="realm-quest ${done?'done':''}"><b>${done?'✓':'◷'} ${q.title}</b><small>${q.desc}</small><small>${Math.min(n,q.target)} / ${q.target} · ${done?'REWARD CLAIMED':'+42 XP & 3 scrap'}</small><progress value="${Math.min(q.target,n)}" max="${q.target}"></progress></article>`}).join('');$('realmFieldStats').innerHTML=[[S.stats.kills,'HOSTILES DEFEATED'],[S.known.length,'REGIONS FOUND'],[S.stats.crafts,'ITEMS CRAFTED'],[S.records.riftWins,'RIFT WINS'],[S.records.expeditionWins,'IRONMAN WINS'],[complete+'/'+QUESTS.length,'QUESTS CLEARED']].map(([v,label])=>`<div><b>${v}</b><span>${label}</span></div>`).join('')}
function renderInventory(){const content=Object.entries(ITEM).map(([id,[icon,name]])=>`<button type="button" data-item="${id}" class="realm-item" title="Inspect ${name}"><b>${icon}</b><strong>${S.inventory[id]||0}</strong><small>${name}</small></button>`).join('');$('realmInventory').innerHTML=content}
function inspectItem(id){if(!ITEM[id])return;const item=document.querySelector(`[data-item="${id}"]`);document.querySelectorAll('.realm-item.selected').forEach(x=>x.classList.remove('selected'));if(item){item.classList.remove('realm-card-select');void item.offsetWidth;item.classList.add('selected','realm-card-select')}const info=$('realmItemDetail');if(info){const note={wood:'Build shelters and fletch arrows.',stone:'Craft campfires, arrows and runes.',berries:'Edible wilderness fruit.',herb:'Medicinal plants for healing bandages.',meat:'Hunt wildlife to make nourishing stew.',soup:'Warm meals cure hunger and cold.',bandage:'Bandages restore 45 vitality.',arrows:'Ammo for your Huntsman bow.',scrap:'Remnants of ancient machinery.',runes:'Treasure from forgotten ruins.',riftKeys:'Spend a key to enter the five-wave Frostbound Rift.'}[id]||'A useful material';info.textContent=`${ITEM[id][1]} · ${S.inventory[id]||0} in pack. ${note}`}}

function renderCraft(){const items=Object.entries(CRAFT).map(([id,r])=>{const cost=Object.entries(r.cost).map(([name,n])=>`${n} ${ITEM[name]?.[1]||name}`).join(' · ');return `<article class="realm-recipe ${lastCraftGlow===id?'realm-card-select':''}"><div><b>⚒ ${r.name}</b><small>${r.desc}</small><small>${cost}</small></div><button data-craft="${id}" ${canCraft(r)?'':'disabled'}>CRAFT</button></article>`}).join('');$('realmCrafting').innerHTML=items}
