function learnPerk(id){if(!PERKS[id])return;const rank=perkRank(id);if(rank>=2){toast('This path has been mastered.');return}if(skillPointsAvailable()<1){toast('Earn another adventurer level to gain a talent point.');return}S.player.skillPoints--;S.perks[id]=rank+1;if(id==='ironheart')S.player.hp=Math.min(maxHP(),S.player.hp+20);lastForgeGlow=id;setDirty();ping('loot');toast(`✧ TALENT AWAKENED: ${PERKS[id].title} · ${rank+1}/2`);renderPanel()}
