function onPointerAction(e){const inspected=e.target.closest('button[data-item]');if(inspected){inspectItem(inspected.dataset.item);return}const shop=e.target.closest('button[data-buy]');if(shop){const card=shop.closest('.realm-shop-item');if(card){card.classList.remove('realm-card-select');void card.offsetWidth;card.classList.add('realm-card-select')}buy(shop.dataset.buy);return}const craftBtn=e.target.closest('button[data-craft]');if(craftBtn){craft(craftBtn.dataset.craft);return}const perk=e.target.closest('button[data-perk]');if(perk){learnPerk(perk.dataset.perk);return}const boon=e.target.closest('button[data-boon]');if(boon){bless(boon.dataset.boon);return}const cmd=e.target.closest('button[data-action]');if(cmd){action(cmd.dataset.action);return}const panel=e.target.closest('[data-panel]');if(panel){openPanel(panel.dataset.panel)}}
