 if(!connected){profileId='practice';try{const saved=JSON.parse(localStorage.getItem(localKey())||'null');if(saved?.v===1)S={...defaultWorld(),...saved};const f=JSON.parse(localStorage.getItem('mo2-arsenal-shiverfell-practice-economy-v1')||'null');if(f&&Array.isArray(f.purchases)&&Number.isFinite(f.credits))offlineStore=f;}catch{}wallet={ok:true,profileId:'practice',earned:0,spent:30-offlineStore.credits,available:offlineStore.credits,verifiedUpdates:0,purchases:offlineStore.purchases,rate:10}}
 try{W=clamp(Number(localStorage.getItem('shiverfell-zoom-v1'))||48,36,66)}catch{}
 S.stats={...defaultWorld().stats,...(S.stats||{})};S.inventory={...defaultWorld().inventory,...(S.inventory||{})};S.player={...defaultWorld().player,...(S.player||{})};S.records={...defaultWorld().records,...(S.records||{})};S.records.receiptsClaimed=Array.isArray(S.records.receiptsClaimed)?S.records.receiptsClaimed:[];S.camp={...defaultWorld().camp,...(S.camp||{})};S.known=Array.isArray(S.known)?S.known:[];S.quests=S.quests||{};S.harvested=S.harvested||{};S.removed=S.removed||{};S.companions=S.companions||[];S.story={fragments:[],wardenDefeated:false,...(S.story||{})};S.perks=Object.fromEntries(Object.entries(S.perks||{}).filter(([k,v])=>PERKS[k]&&Number.isFinite(Number(v))).map(([k,v])=>[k,clamp(Number(v)|0,0,2)]));S.story.fragments=Array.isArray(S.story.fragments)?[...new Set(S.story.fragments.filter(k=>['shrine','watchtower','crypt'].includes(k)))]:[];
 reconcileReceipts();if(S.mode==='rift'&&S.rift?.phase==='combat')spawnRiftWave();else if(S.mode==='rift'&&S.rift?.phase==='blessing')setTimeout(showBlessings,400);
